changeSet.createProcedure:
CREATE FUNCTION public.admit_team_element() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    PERFORM 1 FROM public.team_snapshot s
        JOIN public.team_item_version v ON v.id = s.version_id AND v.workspace_id = s.workspace_id
        WHERE s.id = NEW.snapshot_id AND s.workspace_id = NEW.workspace_id AND v.state = 'AVAILABLE'
        AND v.created_in_transaction = pg_current_xact_id()::text::bigint
        FOR SHARE OF v;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'an element arrives only with its new team item version' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END $$

CREATE FUNCTION public.keep_team_element_of_available_version() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    -- Where the snapshot is being deleted or its version has ended, nothing is found.
    PERFORM 1 FROM public.team_snapshot s
        JOIN public.team_item_version v ON v.id = s.version_id AND v.workspace_id = s.workspace_id
        WHERE s.id = OLD.snapshot_id AND s.workspace_id = OLD.workspace_id AND v.state = 'AVAILABLE';
    IF FOUND THEN
        RAISE EXCEPTION 'an element is deleted only with its version''s content' USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END $$

changeSet.sql:
CREATE TRIGGER team_element_admit BEFORE INSERT ON public.team_element
    FOR EACH ROW EXECUTE FUNCTION public.admit_team_element();
CREATE TRIGGER team_element_guard AFTER UPDATE ON public.team_element
    FOR EACH ROW EXECUTE FUNCTION public.refuse_team_content_change();
CREATE TRIGGER team_element_kept AFTER DELETE ON public.team_element
    FOR EACH ROW EXECUTE FUNCTION public.keep_team_element_of_available_version();

changeSet.rollback:
DROP TRIGGER team_element_kept ON public.team_element;
DROP TRIGGER team_element_guard ON public.team_element;
DROP TRIGGER team_element_admit ON public.team_element;
DROP FUNCTION public.keep_team_element_of_available_version();
DROP FUNCTION public.refuse_team_content_change();
DROP FUNCTION public.admit_team_element();

changeSet.createProcedure:
CREATE FUNCTION public.admit_team_context() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    PERFORM 1 FROM public.team_item_version v
        WHERE v.id = NEW.version_id AND v.workspace_id = NEW.workspace_id AND v.state = 'AVAILABLE'
        AND v.created_in_transaction = pg_current_xact_id()::text::bigint
        FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'a note arrives only with its new team item version' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END $$

CREATE OR REPLACE FUNCTION public.delete_ended_team_version_content() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    DELETE FROM public.team_snapshot s WHERE s.version_id = NEW.id AND s.workspace_id = NEW.workspace_id;
    DELETE FROM public.team_context c WHERE c.version_id = NEW.id AND c.workspace_id = NEW.workspace_id;
    RETURN NULL;
END $$

changeSet.sql:
CREATE TRIGGER team_context_admit BEFORE INSERT ON public.team_context
    FOR EACH ROW EXECUTE FUNCTION public.admit_team_context();
CREATE TRIGGER team_context_guard AFTER UPDATE ON public.team_context
    FOR EACH ROW EXECUTE FUNCTION public.refuse_team_content_change();

changeSet.rollback:
DROP TRIGGER team_context_guard ON public.team_context;
DROP TRIGGER team_context_admit ON public.team_context;
DROP FUNCTION public.admit_team_context();
CREATE OR REPLACE FUNCTION public.delete_ended_team_version_content() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    DELETE FROM public.team_snapshot s WHERE s.version_id = NEW.id AND s.workspace_id = NEW.workspace_id;
    RETURN NULL;
END $$;
